    #[doc = " `ProtocolIE-Field`: an IE of a protocol IE container, and a `ProtocolIE-SingleContainer`."]
    #[doc = " The object set of a container does not show in its type: `value` is an open type."]
    #[derive(AsnType, Debug, Clone, Decode, Encode, PartialEq, Eq, Hash)]
    #[rasn(automatic_tags, identifier = "ProtocolIE-Field")]
    pub struct ProtocolIEField {
        pub id: ProtocolIEID,
        pub criticality: Criticality,
        pub value: Any,
    }
    impl ProtocolIEField {
        pub fn new(id: impl Into<ProtocolIEID>, criticality: Criticality, value: Any) -> Self {
            Self {
                id: id.into(),
                criticality,
                value,
            }
        }
    }
    #[doc = " `ProtocolIE-Container`: the IEs of a message."]
    #[derive(AsnType, Debug, Clone, PartialEq, Eq, Hash)]
    #[rasn(delegate, size("0..=65535"), identifier = "ProtocolIE-Container")]
    pub struct ProtocolIEContainer(pub SequenceOf<ProtocolIEField>);
    impl Encode for ProtocolIEContainer {
        fn encode_with_tag_and_constraints<'b, E: Encoder<'b>>(
            &self,
            encoder: &mut E,
            tag: Tag,
            constraints: Constraints,
            identifier: Identifier,
        ) -> Result<(), E::Error> {
            if encoder.codec() != rasn::Codec::Aper {
                return encoder
                    .encode_sequence_of(tag, &self.0, constraints, identifier)
                    .map(drop);
            }
            const LENGTH_CONSTRAINTS: Constraints =
                rasn::constraints!(rasn::value_constraint!(0, 65535));
            let _ = encoder.encode_integer(
                Tag::INTEGER,
                LENGTH_CONSTRAINTS,
                &self.0.len(),
                Identifier::EMPTY,
            )?;
            for value in &self.0 {
                value.encode(encoder)?;
            }
            Ok(())
        }
    }
    impl Decode for ProtocolIEContainer {
        fn decode_with_tag_and_constraints<D: Decoder>(
            decoder: &mut D,
            tag: Tag,
            constraints: Constraints,
        ) -> Result<Self, D::Error> {
            if decoder.codec() != rasn::Codec::Aper {
                return decoder
                    .decode_sequence_of::<ProtocolIEField>(tag, constraints)
                    .map(Self);
            }
            const LENGTH_CONSTRAINTS: Constraints =
                rasn::constraints!(rasn::value_constraint!(0, 65535));
            let length = decoder.decode_integer::<usize>(Tag::INTEGER, LENGTH_CONSTRAINTS)?;
            let mut values = Vec::new();
            for _ in 0..length {
                values.push(ProtocolIEField::decode(decoder)?);
            }
            Ok(Self(values))
        }
    }
